/// This object describes the way a background is filled based on the selected colors.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type")]
pub enum BackgroundFill {
    /// The background is filled using the selected color.
    #[serde(rename = "solid")]
    Solid(BackgroundFillSolid),
    /// The background is a gradient fill.
    #[serde(rename = "gradient")]
    Gradient(BackgroundFillGradient),
    /// The background is a freeform gradient that rotates after every message in the chat.
    #[serde(rename = "freeform_gradient")]
    FreeformGradient(BackgroundFillFreeformGradient),
    /// A kind added to the Bot API after this layer was generated.
    #[serde(other)]
    Unknown,
}

/// The background is filled using the selected color.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct BackgroundFillSolid {
    /// The color of the background fill in the RGB24 format
    pub color: i64,
}

/// The background is a gradient fill.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct BackgroundFillGradient {
    /// Top color of the gradient in the RGB24 format
    pub top_color: i64,
    /// Bottom color of the gradient in the RGB24 format
    pub bottom_color: i64,
    /// Clockwise rotation angle of the background fill in degrees; 0-359
    pub rotation_angle: i64,
}

/// The background is a freeform gradient that rotates after every message in the chat.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct BackgroundFillFreeformGradient {
    /// A list of the 3 or 4 base colors that are used to generate the freeform gradient in the RGB24 format
    pub colors: Vec<i64>,
}

/// This object describes the type of a background.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type")]
pub enum BackgroundType {
    /// The background is automatically filled based on the selected colors.
    #[serde(rename = "fill")]
    Fill(BackgroundTypeFill),
    /// The background is a wallpaper in the JPEG format.
    #[serde(rename = "wallpaper")]
    Wallpaper(BackgroundTypeWallpaper),
    /// The background is a .PNG or .TGV (gzipped subset of SVG with MIME type "application/x-tgwallpattern") pattern to
    /// be combined with the background fill chosen by the user.
    #[serde(rename = "pattern")]
    Pattern(BackgroundTypePattern),
    /// The background is taken directly from a built-in chat theme.
    #[serde(rename = "chat_theme")]
    ChatTheme(BackgroundTypeChatTheme),
    /// A kind added to the Bot API after this layer was generated.
    #[serde(other)]
    Unknown,
}

/// The background is automatically filled based on the selected colors.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct BackgroundTypeFill {
    /// The background fill
    pub fill: BackgroundFill,
    /// Dimming of the background in dark themes, as a percentage; 0-100
    pub dark_theme_dimming: i64,
}

/// The background is a wallpaper in the JPEG format.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct BackgroundTypeWallpaper {
    /// Document with the wallpaper
    pub document: Document,
    /// Dimming of the background in dark themes, as a percentage; 0-100
    pub dark_theme_dimming: i64,
    /// True, if the wallpaper is downscaled to fit in a 450x450 square and then box-blurred with radius 12
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub is_blurred: Option<bool>,
    /// True, if the background moves slightly when the device is tilted
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub is_moving: Option<bool>,
}

/// The background is a .PNG or .TGV (gzipped subset of SVG with MIME type "application/x-tgwallpattern") pattern to be
/// combined with the background fill chosen by the user.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct BackgroundTypePattern {
    /// Document with the pattern
    pub document: Document,
    /// The background fill that is combined with the pattern
    pub fill: BackgroundFill,
    /// Intensity of the pattern when it is shown above the filled background; 0-100
    pub intensity: i64,
    /// True, if the background fill must be applied only to the pattern itself.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub is_inverted: Option<bool>,
    /// True, if the background moves slightly when the device is tilted
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub is_moving: Option<bool>,
}

