/// This object represents a game.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Game {
    /// Title of the game
    pub title: String,
    /// Description of the game
    pub description: String,
    /// Photo that will be displayed in the game message in chats
    pub photo: Vec<PhotoSize>,
    /// Brief description of the game or high scores included in the game message.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub text: Option<String>,
    /// Special entities that appear in text, such as usernames, URLs, bot commands, etc.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub text_entities: Option<Vec<MessageEntity>>,
    /// Animation that will be displayed in the game message in chats.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub animation: Option<Animation>,
}

/// A placeholder, currently holds no information.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct CallbackGame {}

/// This object represents one row of the high scores table for a game.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct GameHighScore {
    /// Position in high score table for the game
    pub position: i64,
    /// User
    pub user: User,
    /// Score
    pub score: i64,
}

/// A media element embedded in an outgoing rich message.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type")]
pub enum InputRichMedia {
    /// Represents an animation file (GIF or H.264/MPEG-4 AVC video without sound) to be sent.
    #[serde(rename = "animation")]
    Animation(InputMediaAnimation),
    /// Represents an audio file to be treated as music to be sent.
    #[serde(rename = "audio")]
    Audio(InputMediaAudio),
    /// Represents a general file to be sent.
    #[serde(rename = "document")]
    Document(InputMediaDocument),
    /// Represents a photo to be sent.
    #[serde(rename = "photo")]
    Photo(InputMediaPhoto),
    /// Represents a video to be sent.
    #[serde(rename = "video")]
    Video(InputMediaVideo),
    /// Represents a voice message file to be sent.
    #[serde(rename = "voice_note")]
    VoiceNote(InputMediaVoiceNote),
}

/// A keyboard to attach to a message, or an instruction to remove or replace one.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum ReplyMarkup {
    /// This object represents an inline keyboard that appears right next to the message it belongs to.
    InlineKeyboardMarkup(InlineKeyboardMarkup),
    /// This object represents a custom keyboard with reply options (see Introduction to bots for details and examples).
    ReplyKeyboardMarkup(ReplyKeyboardMarkup),
    /// Upon receiving a message with this object, Telegram clients will remove the current custom keyboard and display
    /// the default letter-keyboard.
    ReplyKeyboardRemove(ReplyKeyboardRemove),
    /// Upon receiving a message with this object, Telegram clients will display a reply interface to the user (act as
    /// if the user has selected the bot's message and tapped 'Reply').
    ForceReply(ForceReply),
}

/// The edited message, or `true` when it was an inline message.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum MessageOrBool {
    /// This object represents a message.
    Message(Box<Message>),
    /// `true`.
    Bool(bool),
}
